import json, subprocess

with open("help_cache.json") as f:
    helps = json.load(f)

cmd_behaviors = {}

for key in helps.keys():
    if key.startswith("__"): continue
    r = subprocess.run(["./executable", key], capture_output=True, text=True)
    # Strip header and quote from stderr
    stderr_lines = r.stderr.splitlines()
    # Find start of error message or body
    filtered_err = []
    in_body = False
    for line in stderr_lines:
        if line.startswith("-------------------------------------------------------"):
            in_body = True
        if in_body:
            filtered_err.append(line)

    cmd_behaviors[key] = {
        "returncode": r.returncode,
        "stdout": r.stdout,
        "stderr_body": "\n".join(filtered_err)
    }

