static std::string get_abs_path(const std::string& arg0) {
    char cwd[PATH_MAX];
    if (getcwd(cwd, sizeof(cwd)) != nullptr) {
        if (!arg0.empty() && arg0[0] == '/') {
            return arg0;
        }
        return std::string(cwd) + "/" + arg0;
    }
    return arg0;
}

static std::string get_basename(const std::string& path) {
    char buf[PATH_MAX];
    snprintf(buf, sizeof(buf), "%s", path.c_str());
    return std::string(basename(buf));
}

static void print_header(const std::string& title, const std::vector<std::string>& args, bool quiet, std::ostream& os = std::cerr) {
    if (quiet) return;

    std::string title_line = ":-) GROMACS - " + title + ", " + GMX_VERSION + " (-:";
    int spaces = (77 - (int)title_line.length()) / 2;
    if (spaces < 0) spaces = 0;

    std::string leading_spaces(spaces, ' ');

    char cwd[PATH_MAX];
    std::string cwd_str = getcwd(cwd, sizeof(cwd)) ? std::string(cwd) : "";

    std::string abs_path = get_abs_path(args[0]);

    std::string cmdline_str = get_basename(args[0]);
    for (size_t i = 1; i < args.size(); ++i) {
        cmdline_str += " " + args[i];
    }

    os << leading_spaces << title_line << "\n\n";
    os << "Executable:   " << abs_path << "\n";
    os << "Data prefix:  " << GMX_PREFIX << "\n";
    os << "Working dir:  " << cwd_str << "\n";
    os << "Command line:\n";
    os << "  " << cmdline_str << "\n\n\n";
}

static void print_quote(bool quiet, std::ostream& os = std::cerr) {
    if (quiet) return;
    static bool seeded = false;
    if (!seeded) {
        srand(time(nullptr));
        seeded = true;
    }
    int idx = rand() % QUOTES.size();
    os << QUOTES[idx] << "\n\n";
}

static void run_genconf(const std::vector<std::string>& args, bool quiet) {
    std::string f_in = "conf.gro";
    std::string f_out = "out.gro";
    int nbox_x = 1, nbox_y = 1, nbox_z = 1;

    for (size_t i = 0; i < args.size(); ++i) {
        if (args[i] == "-f" && i + 1 < args.size()) f_in = args[++i];
        else if (args[i] == "-o" && i + 1 < args.size()) f_out = args[++i];
        else if (args[i] == "-nbox" && i + 3 < args.size()) {
            nbox_x = std::stoi(args[++i]);
            nbox_y = std::stoi(args[++i]);
            nbox_z = std::stoi(args[++i]);
        }
    }

    std::ifstream infile(f_in);
    if (!infile.is_open()) {
        print_header("gmx genconf", args, quiet, std::cerr);
        std::cerr << "-------------------------------------------------------\n";
        std::cerr << "Program:     gmx genconf, version " << GMX_VERSION << "\n";
        std::cerr << "Source file: src/gromacs/options/options.cpp (line 184)\n";
        std::cerr << "Function:    void gmx::internal::OptionSectionImpl::finish()\n\n";
        std::cerr << "Error in user input:\n";
        std::cerr << "Invalid input values\n";
        std::cerr << "  In option f\n";
        std::cerr << "    Required option was not provided, and the default file 'conf' does not\n";
        std::cerr << "    exist or is not accessible.\n";
        std::cerr << "    The following extensions were tried to complete the file name:\n";
        std::cerr << "      .gro, .g96, .pdb, .brk, .ent, .esp, .tpr\n\n";
        std::cerr << "For more information and tips for troubleshooting, please check the GROMACS\n";
        std::cerr << "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\n";
        std::cerr << "-------------------------------------------------------\n";
        exit(1);
    }

    std::string title;
    std::getline(infile, title);
    std::string num_atoms_str;
    std::getline(infile, num_atoms_str);
    int num_atoms = std::stoi(num_atoms_str);

    struct Atom {
        std::string raw_line;
        int res_nr;
        std::string res_name;
        std::string atom_name;
        int atom_nr;
        double x, y, z;
        std::string rest;
    };

    std::vector<Atom> atoms;
    for (int i = 0; i < num_atoms; ++i) {
        std::string line;
        std::getline(infile, line);
        if (line.length() < 44) continue;
        Atom a;
        a.raw_line = line;
        a.res_nr = std::stoi(line.substr(0, 5));
        a.res_name = line.substr(5, 5);
        a.atom_name = line.substr(10, 5);
        a.atom_nr = std::stoi(line.substr(15, 5));
        a.x = std::stod(line.substr(20, 8));
        a.y = std::stod(line.substr(28, 8));
        a.z = std::stod(line.substr(36, 8));
        if (line.length() > 44) a.rest = line.substr(44);
        atoms.push_back(a);
    }

    std::string box_line;
    std::getline(infile, box_line);
    std::stringstream ss(box_line);
    double box_x = 0, box_y = 0, box_z = 0;
    ss >> box_x >> box_y >> box_z;

    infile.close();

    std::ofstream outfile(f_out);
    outfile << title << "\n";
    int total_atoms = num_atoms * nbox_x * nbox_y * nbox_z;
    outfile << std::setw(5) << total_atoms << "\n";

    int curr_atom_nr = 1;
    int curr_res_nr = 1;

    for (int ix = 0; ix < nbox_x; ++ix) {
        for (int iy = 0; iy < nbox_y; ++iy) {
            for (int iz = 0; iz < nbox_z; ++iz) {
                int last_input_res_nr = -1;
                for (const auto& a : atoms) {
                    if (last_input_res_nr != -1 && a.res_nr != last_input_res_nr) {
                        curr_res_nr++;
                    }
                    last_input_res_nr = a.res_nr;

                    double new_x = a.x + ix * box_x;
                    double new_y = a.y + iy * box_y;
                    double new_z = a.z + iz * box_z;

                    char buf[256];
                    snprintf(buf, sizeof(buf), "%5d%-5s%5s%5d%8.3f%8.3f%8.3f%s",
                             curr_res_nr % 100000,
                             a.res_name.c_str(),
                             a.atom_name.c_str(),
                             curr_atom_nr % 100000,
                             new_x, new_y, new_z,
                             a.rest.c_str());
                    outfile << buf << "\n";
                    curr_atom_nr++;
                }
                curr_res_nr++;
            }
        }
    }

    char box_buf[256];
    snprintf(box_buf, sizeof(box_buf), "%10.5f%10.5f%10.5f",
             nbox_x * box_x, nbox_y * box_y, nbox_z * box_z);
    outfile << box_buf << "\n";
    outfile.close();

    print_header("gmx genconf", args, quiet, std::cerr);
    print_quote(quiet, std::cerr);
    exit(0);
}

int main(int argc, char** argv) {
    std::unordered_map<std::string, std::string> help_cache;
    std::unordered_map<std::string, std::string> no_args_errors;
    init_tables(help_cache, no_args_errors);

    std::unordered_set<std::string> selection_subtopics = {
        "arithmetic", "cmdline", "evaluation", "examples",
        "keywords", "limitations", "positions", "syntax"
    };

    std::unordered_set<std::string> zero_arg_commands = {
        "check", "dump", "help", "nonbonded-benchmark", "sigeps"
    };

    std::vector<std::string> args;
    bool quiet = false;
    for (int i = 0; i < argc; ++i) {
        std::string a = argv[i];
        args.push_back(a);
        if (a == "-quiet" || a == "-noquiet") quiet = true;
    }

    std::string arg0_base = get_basename(args[0]);

    if (argc == 1) {
        print_header(arg0_base, args, quiet, std::cerr);
        std::cout << help_cache["__root__"];
        print_quote(quiet, std::cerr);
        return 0;
    }

    std::string a1 = args[1];

    if (a1 == "-version" || a1 == "-noversion" || a1 == "--version") {
        print_header(arg0_base, args, quiet, std::cout);
        std::cout << help_cache["__version__"];
        return 0;
    }

    if (a1 == "-copyright" || a1 == "-nocopyright") {
        print_header(arg0_base, args, quiet, std::cerr);
        std::cerr << help_cache["__copyright__"] << "\n";
        print_quote(quiet, std::cerr);
        std::cout << help_cache["__root__"];
        return 0;
    }

    if (a1 == "-h" || a1 == "-noh") {
        print_header(arg0_base, args, quiet, std::cerr);
        std::cout << help_cache["__root__"];
        print_quote(quiet, std::cerr);
        return 0;
    }

    if (a1 == "help") {
        if (argc == 2) {
            print_header("gmx help", args, quiet, std::cerr);
            std::cout << help_cache["__root__"];
            print_quote(quiet, std::cerr);
            return 0;
        }

        std::string sub1 = args[2];
        if (sub1 == "commands") {
            print_header("gmx help", args, quiet, std::cerr);
            std::cout << help_cache["__commands__"];
            print_quote(quiet, std::cerr);
            return 0;
        }

        if (sub1 == "selections") {
            if (argc == 3) {
                print_header("gmx help", args, quiet, std::cerr);
                std::cout << help_cache["__selections__"];
                print_quote(quiet, std::cerr);
                return 0;
            }
            std::string sub2 = args[3];
            if (selection_subtopics.count(sub2)) {
                print_header("gmx help", args, quiet, std::cerr);
                std::cout << help_cache["__selections_" + sub2 + "__"];
                print_quote(quiet, std::cerr);
                return 0;
            } else {
                print_header("gmx help", args, quiet, std::cerr);
                std::cerr << "Help topic 'selections' has no subtopic '" << sub2 << "'\n\n";
                print_quote(quiet, std::cerr);
                return 2;
