static std::string get_abs_path(const std::string& arg0) {
    char cwd[PATH_MAX];
    if (getcwd(cwd, sizeof(cwd)) != nullptr) {
        if (!arg0.empty() && arg0[0] == '/') {
            return arg0;
        }
        return std::string(cwd) + "/" + arg0;
    }
    return arg0;
}

static std::string get_basename(const std::string& path) {
    char buf[PATH_MAX];
    snprintf(buf, sizeof(buf), "%s", path.c_str());
    return std::string(basename(buf));
}

static void print_header(const std::string& title, const std::vector<std::string>& args, bool quiet, std::ostream& os = std::cerr) {
    if (quiet) return;

    std::string title_line = ":-) GROMACS - " + title + ", " + GMX_VERSION + " (-:";
    int spaces = (77 - (int)title_line.length()) / 2;
    if (spaces < 0) spaces = 0;

    std::string leading_spaces(spaces, ' ');

    char cwd[PATH_MAX];
    std::string cwd_str = getcwd(cwd, sizeof(cwd)) ? std::string(cwd) : "";

    std::string abs_path = get_abs_path(args[0]);

