    if (quiet) return;
    static bool seeded = false;
    if (!seeded) {
        srand(time(nullptr));
        seeded = true;
    }
    int idx = rand() % QUOTES.size();
    os << "\\n" << QUOTES[idx] << "\\n\\n";
}

