    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "-quiet" || a == "-noquiet") {
            quiet = true;
        } else if (a == "-backup" || a == "-nobackup") {
            // ignore global backup flag
        } else {
            pos_args.push_back(a);
        }
    }

    std::string arg0_base = get_basename(orig_args[0]);

    if (pos_args.empty()) {
        print_header(arg0_base, orig_args, quiet, std::cerr);
