        print_quote(quiet, std::cerr);
        std::cout << help_cache["__root__"];
        return 0;
    }

    if (a1 == "help") {
        if (pos_args.size() == 1) {
            print_header("gmx help", orig_args, quiet, std::cerr);
            print_quote(quiet, std::cerr);
            std::cout << help_cache["__root__"];
            return 0;
        }

        std::string sub1 = pos_args[1];
        if (sub1 == "commands") {
            print_header("gmx help", orig_args, quiet, std::cerr);
            print_quote(quiet, std::cerr);
            std::cout << help_cache["__commands__"];
            return 0;
        }

        if (sub1 == "selections") {
            if (pos_args.size() == 2) {
                print_header("gmx help", orig_args, quiet, std::cerr);
                print_quote(quiet, std::cerr);
                std::cout << help_cache["__selections__"];
                return 0;
            }
            std::string sub2 = pos_args[2];
            if (selection_subtopics.count(sub2)) {
                print_header("gmx help", orig_args, quiet, std::cerr);
                print_quote(quiet, std::cerr);
                std::cout << help_cache["__selections_" + sub2 + "__"];
                return 0;
            } else {
                print_header("gmx help", orig_args, quiet, std::cerr);
                std::cerr << "Help topic \'selections\' has no subtopic \'" << sub2 << "\'\\n";
                print_quote(quiet, std::cerr);
                return 2;
            }
        }

        if (help_cache.count(sub1)) {
            print_header("gmx help", orig_args, quiet, std::cerr);
            print_quote(quiet, std::cerr);
            std::cout << help_cache[sub1];
            return 0;
        }

        print_header("gmx help", orig_args, quiet, std::cerr);
        std::cerr << "No help available for \'" << sub1 << "\'\\n";
        print_quote(quiet, std::cerr);
        return 2;
    }

    if (a1[0] == '-') {
        if (a1 == "-nice") {
            print_header(arg0_base, orig_args, quiet, std::cerr);
            std::cerr << "-------------------------------------------------------\\n";
            std::cerr << "Program:     " << arg0_base << ", version " << GMX_VERSION << "\\n";
            std::cerr << "Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\\n";
            std::cerr << "Function:    void gmx::CommandLineParser::parse(int*, char**)\\n\\n";
            std::cerr << "Error in user input:\\n";
            std::cerr << "Invalid command-line options\\n";
            std::cerr << "  In command-line option -nice\\n";
            std::cerr << "    Too few (valid) values\\n\\n";
            std::cerr << "For more information and tips for troubleshooting, please check the GROMACS\\n";
            std::cerr << "website at https://manual.gromacs.org/current/user-guide/run-time-errors.html\\n";
            std::cerr << "-------------------------------------------------------\\n";
            return 1;
        }

        print_header(arg0_base, orig_args, quiet, std::cerr);
        std::cerr << "-------------------------------------------------------\\n";
        std::cerr << "Program:     " << arg0_base << ", version " << GMX_VERSION << "\\n";
        std::cerr << "Source file: src/gromacs/commandline/cmdlineparser.cpp (line 271)\\n";
